code_sketch:
abstract record Msg;
sealed record OrderCreated(Order Order) : Msg;
sealed record InvoiceIssued(Invoice Invoice) : Msg;

Task Route(Msg msg) => msg switch
{
    OrderCreated { Order.Amount: > 10_000 } => reviewQueue.Send(msg),
    OrderCreated o                          => orders.Send(o.Order),
    InvoiceIssued i                         => invoices.Send(i.Invoice),
    _                                       => deadLetter.Send(msg)   // fallback
};

